script:
listing = env.run(["ls", "-R"], check=False)
res = env.run(["cargo", "test", "--no-fail-fast"], check=False)
return {"listing": listing.stdout[:3000], "code": res.code, "stdout": res.stdout, "stderr": res.stderr}

a = env.run(["cargo", "test", "--verbose"], check=False)
b = env.run(["cargo", "test", "--", "--nocapture"], check=False)
return {"verbose_code": a.code, "verbose_out": a.stdout, "verbose_err": a.stderr, "nocap_code": b.code, "nocap_out": b.stdout, "nocap_err": b.stderr}
